<?php
declare(strict_types=1);
require_once __DIR__.'/SemanticValidator.php';
require_once __DIR__.'/GuidePaymentDueDatePolicy.php';

/** Geração local GNRE v2.00 pelo contrato oficial persistido. */
final class GnreXmlGenerator
{
    private const NS='http://www.gnre.pe.gov.br';
    private const XSD=GNRE_MODULE.'/docs/referencias/gnre-v2.17/lote_gnre_v2.00.xsd';
    private const TYPES=['11','12','21','22','31','32','41','42','51','52'];
    /** Validates the exact data set later serialized by generate(), without creating XML. */
    public function validateInput(array $guide,array $items,?array $rules=null,?array $emitter=null):array {
        $errors=(new GuidePaymentDueDatePolicy())->validate((string)($guide['GNRE001_Data_Pagamento']??''),$items);$errors=array_merge($errors,$this->business($guide,$items)); $valueMode=''; if($rules===null)$errors[]='Carregue a configuração oficial da UF antes de gerar o XML.';else {$errors=array_merge($errors,GnreConfigUfRules::validate($rules,$guide,$items,$emitter));$errors=array_merge($errors,(new GnreSemanticValidator())->validate($rules,$emitter??[],$items));$valueMode=$this->valueMode($rules,$items);if($valueMode==='mixed')$errors[]='A combinação de receitas com cálculo pela UF e receitas com valores informados não é suportada no mesmo XML.';}
        if($rules!==null&&$valueMode!=='all_n'){ $old=trim((string)($guide['GNRE001_Valor']??''));if($old!==''&&abs($this->total($items)-(float)$old)>.004)$errors[]='Compatibilidade: o valor legado do cabeçalho diverge da soma dos valores tributários dos itens; revise a guia sem alteração automática.'; }
        return ['errors'=>array_values(array_unique($errors)),'value_mode'=>$valueMode];
    }
    public function generate(array $guide,array $items,?array $rules=null,?array $emitter=null):array {
        if(!class_exists('DOMDocument'))return ['xml'=>'','errors'=>['A extensão DOM do PHP é necessária para gerar e validar o XML GNRE.']];
        $validation=$this->validateInput($guide,$items,$rules,$emitter);$errors=$validation['errors'];$valueMode=$validation['value_mode'];
        if($errors)return ['xml'=>'','errors'=>$errors];
        $dom=new DOMDocument('1.0','UTF-8');$dom->formatOutput=true;$l=$this->e($dom,'TLote_GNRE');$l->setAttribute('versao','2.00');$dom->appendChild($l);$d=$this->e($dom,'TDadosGNRE',$this->e($dom,'guias',$l));$d->setAttribute('versao','2.00');
        $this->e($dom,'ufFavorecida',$d,(string)$guide['GNRE001_UF_Favorecida']);$this->e($dom,'tipoGnre',$d,(string)$guide['GNRE001_Tipo_GNRE']);
        if($emitter!==null&&empty($emitter['errors'])&&$this->needsEmitter($rules,$items))$this->emitter($dom,$d,$emitter,$rules);
        $is=$this->e($dom,'itensGNRE',$d);foreach($items as $item)$this->item($dom,$is,$item);if($valueMode!=='all_n')$this->e($dom,'valorGNRE',$d,number_format($this->total($items),2,'.',''));
        if(trim((string)($guide['GNRE001_Data_Pagamento']??''))!=='')$this->e($dom,'dataPagamento',$d,(string)$guide['GNRE001_Data_Pagamento']);
        $xml=$dom->saveXML();return is_string($xml)?['xml'=>$xml,'errors'=>$this->xsd($dom)]:['xml'=>'','errors'=>['Não foi possível serializar o XML GNRE.']];
    }
    private function needsEmitter(array $rules,array $items):bool {foreach($items as $i){$r=GnreConfigUfRules::receipt($rules,(string)$i['GNRE003_Codigo_Receita']);if($r&&($r['fields']['emitter']??'N')!=='N')return true;}return false;}
    private function emitter(DOMDocument $d,DOMElement $p,array $x,array $rules):void {$n=$this->e($d,'contribuinteEmitente',$p);$i=$this->e($d,'identificacao',$n);$this->e($d,'CNPJ',$i,$x['cnpj']);$this->e($d,'razaoSocial',$n,trim((string)$x['name']));if(($rules['address_required']['cnpj']??'N')==='S')foreach(['address'=>'endereco','city'=>'municipio','uf'=>'uf','cep'=>'cep','phone'=>'telefone']as $k=>$t)$this->e($d,$t,$n,$x[$k]);}
    private function item(DOMDocument $d,DOMElement $p,array $i):void {$n=$this->e($d,'item',$p);$this->e($d,'receita',$n,(string)$i['GNRE003_Codigo_Receita']);if(!empty($i['GNRE003_Detalhamento_Receita']))$this->e($d,'detalhamentoReceita',$n,(string)$i['GNRE003_Detalhamento_Receita']);if(!empty($i['GNRE002_Identificacao'])){$x=$this->e($d,'documentoOrigem',$n,(string)$i['GNRE002_Identificacao']);$x->setAttribute('tipo',(string)$i['GNRE003_Tipo_Documento_Origem']);}if(!empty($i['GNRE003_Codigo_Produto']))$this->e($d,'produto',$n,(string)$i['GNRE003_Codigo_Produto']);if($this->ref($i)){$r=$this->e($d,'referencia',$n);foreach(['Periodo'=>'periodo','Mes'=>'mes','Ano'=>'ano','Parcela'=>'parcela']as $k=>$t)if(!empty($i['GNRE003_Referencia_'.$k]))$this->e($d,$t,$r,(string)$i['GNRE003_Referencia_'.$k]);}if(!empty($i['GNRE003_Data_Vencimento']))$this->e($d,'dataVencimento',$n,(string)$i['GNRE003_Data_Vencimento']);foreach($this->values($i)as $v){$x=$this->e($d,'valor',$n,number_format((float)$v['value'],2,'.',''));$x->setAttribute('tipo',$v['type']);}if(!empty($i['GNRE003_Convenio']))$this->e($d,'convenio',$n,(string)$i['GNRE003_Convenio']);if(!empty($i['GNRE003_Destinatario_Identificacao'])){$dest=$this->e($d,'contribuinteDestinatario',$n);$ident=$this->e($d,'identificacao',$dest);$this->e($d,(string)$i['GNRE003_Destinatario_Tipo_Identificacao'],$ident,(string)$i['GNRE003_Destinatario_Identificacao']);$name=trim((string)($i['GNRE003_Destinatario_Razao_Social']??''));if($name!=='')$this->e($d,'razaoSocial',$dest,$name);$municipality=GnreMunicipality::gnreCode(GnreMunicipality::storedIbge($i));if($municipality!=='')$this->e($d,'municipio',$dest,$municipality);}$extras=$this->extras($i['GNRE003_Campos_Extras_JSON']??null);if($extras){$fs=$this->e($d,'camposExtras',$n);foreach($extras as $v){$f=$this->e($d,'campoExtra',$fs);$this->e($d,'codigo',$f,(string)$v['codigo']);$this->e($d,'valor',$f,$v['valor']);}}}
    private function business(array $g,array $items):array {$e=[];if(!preg_match('/^[A-Z]{2}$/',(string)($g['GNRE001_UF_Favorecida']??'')))$e[]='UF favorecida inválida.';if(!$items||count($items)>100)$e[]='A guia deve ter entre 1 e 100 itens de recolhimento.';foreach($items as $n=>$i){$p='Item '.($n+1).': ';if(!preg_match('/^\d{6}$/',(string)($i['GNRE003_Codigo_Receita']??'')))$e[]=$p.'receita deve ter 6 dígitos.';$v=$this->values($i);if(count($v)>10)$e[]=$p.'possui mais de 10 valores tributários.';foreach($v as $x){if(!in_array($x['type'],self::TYPES,true))$e[]=$p.'tipo de valor inválido.';if((float)$x['value']<=0)$e[]=$p.'valor deve ser maior que zero.';} $id=(string)($i['GNRE003_Destinatario_Identificacao']??'');$type=(string)($i['GNRE003_Destinatario_Tipo_Identificacao']??'');$patterns=['CNPJ'=>'/^\d{14}$/','CPF'=>'/^\d{11}$/','IE'=>'/^\d{2,16}$/'];if($id!==''&&(!isset($patterns[$type])||!preg_match($patterns[$type],$id)))$e[]=$p.'identificação do destinatário inválida.';if($id===''&&($type!==''||!empty($i['GNRE003_Destinatario_Razao_Social'])||!empty($i['GNRE003_Destinatario_Codigo_Municipio'])))$e[]=$p.'dados do destinatário informados sem identificação.';if(!empty($i['GNRE003_Destinatario_Razao_Social'])&&mb_strlen((string)$i['GNRE003_Destinatario_Razao_Social'],'UTF-8')>60)$e[]=$p.'razão social do destinatário excede 60 caracteres.';if(!empty($i['GNRE003_Destinatario_Codigo_Municipio'])&&!preg_match('/^\d{5}$/',(string)$i['GNRE003_Destinatario_Codigo_Municipio']))$e[]=$p.'código do município do destinatário inválido.';if($this->extras($i['GNRE003_Campos_Extras_JSON']??null)===null)$e[]=$p.'campos extras devem ser JSON com até 3 objetos codigo/valor.';}return $e;}
    private function values(array $i):array {$out=[];foreach(($i['GNRE006']??[])as $v)$out[]=['type'=>(string)($v['GNRE006_Tipo_Valor']??$v['type']??''),'value'=>(string)($v['GNRE006_Valor']??$v['value']??'')];return $out;}
    private function total(array $items):float {$s=0.;foreach($items as $i)foreach($this->values($i)as $v)$s+=(float)$v['value'];return $s;}
    private function valueMode(array $rules,array $items):string {$n=false;$contributor=false;$hasValues=false;foreach($items as $item){if($this->values($item))$hasValues=true;$receipt=GnreConfigUfRules::receipt($rules,(string)$item['GNRE003_Codigo_Receita']);if($receipt&&strtoupper((string)($receipt['value']??''))==='N')$n=true;else $contributor=true;}return $n&&$contributor?'mixed':($n&&!$hasValues?'all_n':'contributor');}
    private function xsd(DOMDocument $d):array {$o=libxml_use_internal_errors(true);$ok=$d->schemaValidate(self::XSD);$raw=libxml_get_errors();libxml_clear_errors();libxml_use_internal_errors($o);if($ok)return [];$e=[];foreach($raw as $x)$e[]='XSD linha '.$x->line.': '.trim($x->message);return $e?:['O XML não passou na validação XSD local.'];}
    private function ref(array $i):bool {foreach(['Periodo','Mes','Ano','Parcela']as $x)if(!empty($i['GNRE003_Referencia_'.$x]))return true;return false;}
    private function extras(?string $s):?array {$x=GnreMunicipality::extras($s);if($x===null||count($x)>3)return null;$out=[];foreach($x as $v){if(!is_array($v)||!isset($v['codigo'],$v['valor'])||!is_string($v['valor'])||mb_strlen($v['valor'],'UTF-8')>100)return null;$code=$v['codigo'];if(is_string($code)&&ctype_digit($code))$code=(int)$code;if(!is_int($code))return null;$out[]=['codigo'=>$code,'valor'=>$v['valor']];}return $out;}
    private function e(DOMDocument $d,string $name,?DOMElement $p=null,?string $v=null):DOMElement {$e=$d->createElementNS(self::NS,$name);if($v!==null)$e->appendChild($d->createTextNode($v));if($p)$p->appendChild($e);return $e;}
}
